import { Field } from "@/registry/erbium/ui/field";
import {
  NumberField,
  NumberFieldGroup,
  NumberFieldInput,
  NumberFieldIncrement,
  NumberFieldDecrement,
  NumberFieldScrubArea,
} from "@/registry/erbium/ui/number-field";

export default function NumberFieldShowcaseExample() {
  return (
    <Field>
      <NumberField defaultValue={24} min={0} max={200} className="w-48">
        <NumberFieldScrubArea label="Font size" />
        <NumberFieldGroup>
          <NumberFieldDecrement />
          <NumberFieldInput />
          <NumberFieldIncrement />
        </NumberFieldGroup>
      </NumberField>
    </Field>
  );
}
